INSERT OR IGNORE INTO places (id, title, description, price, latitude, longitude, user_id) VALUES
('10000000-0000-4000-8000-000000000001', 'Studio lumineux a Biarritz', 'Petit studio tres lumineux a deux rues de la plage, ideal pour un sejour surf avec cuisine equipee et coin nuit bien pense.', 95, 43.4832, -1.5586, '11111111-1111-4111-8111-111111111111'),
('10000000-0000-4000-8000-000000000002', 'Duplex calme a Bayonne', 'Duplex chaleureux dans une rue calme, parfait pour teletravailler quelques jours puis rejoindre l ocean en voiture.', 110, 43.4929, -1.4748, '11111111-1111-4111-8111-111111111111'),
('10000000-0000-4000-8000-000000000003', 'Appartement surf a Hossegor', 'Appartement simple et efficace avec balcon, espace planches et ambiance vacances pour profiter du front de mer.', 125, 43.6646, -1.4282, '11111111-1111-4111-8111-111111111111'),
('10000000-0000-4000-8000-000000000004', 'Loft design a Marseille', 'Grand loft au style contemporain dans un quartier vivant, avec belle hauteur sous plafond et acces rapide au Vieux Port.', 150, 43.2965, 5.3698, '22222222-2222-4222-8222-222222222222'),
('10000000-0000-4000-8000-000000000005', 'Cabane chic a Cassis', 'Petite maison renovee avec terrasse et vue degagee, parfaite pour des journees entre calanques et restaurants du port.', 175, 43.2140, 5.5396, '22222222-2222-4222-8222-222222222222'),
('10000000-0000-4000-8000-000000000006', 'Maison de pecheur a Sete', 'Logement plein de caractere pres des quais, avec pieces bien agencees et atmosphere paisible en fin de journee.', 135, 43.4028, 3.6928, '33333333-3333-4333-8333-333333333333'),
('10000000-0000-4000-8000-000000000007', 'T2 vue port a La Rochelle', 'Appartement confortable avec vue sur les toits et le port, pratique pour tout faire a pied pendant un long week end.', 145, 46.1603, -1.1511, '33333333-3333-4333-8333-333333333333'),
('10000000-0000-4000-8000-000000000008', 'Chalet cosy a Chamonix', 'Chalet compact mais tres chaleureux avec boiseries, coin feu et vue montagne pour une semaine sport et repos.', 210, 45.9237, 6.8694, '44444444-4444-4444-8444-444444444444'),
('10000000-0000-4000-8000-000000000009', 'Appartement central a Annecy', 'Appartement moderne a quelques minutes du lac et du centre historique, ideal pour visiter sans voiture.', 160, 45.8992, 6.1294, '44444444-4444-4444-8444-444444444444'),
('10000000-0000-4000-8000-000000000010', 'Villa familiale a Arcachon', 'Grande maison lumineuse avec jardin, belle table pour les repas et acces rapide a la plage pour toute la famille.', 260, 44.6520, -1.1721, '55555555-5555-4555-8555-555555555555'),
('10000000-0000-4000-8000-000000000011', 'Studio canal a Strasbourg', 'Studio bien agence au bord de l eau, parfait pour un city break avec marche local et cafes accessibles a pied.', 105, 48.5734, 7.7521, '55555555-5555-4555-8555-555555555555'),
('10000000-0000-4000-8000-000000000012', 'Maison en pierre a Gordes', 'Maison en pierre restauree avec terrasse ombragee et interieur frais, tres agreable en ete.', 220, 43.9129, 5.2001, '66666666-6666-4666-8666-666666666666'),
('10000000-0000-4000-8000-000000000013', 'Appartement moderne a Lyon', 'Appartement propre et moderne avec cuisine ouverte, bien place pour un sejour urbain ou professionnel.', 130, 45.7640, 4.8357, '66666666-6666-4666-8666-666666666666'),
('10000000-0000-4000-8000-000000000014', 'Petit nid a Saint Malo', 'Adresse simple et charmante proche des remparts, excellente base pour profiter de la mer et des balades.', 140, 48.6493, -2.0257, '77777777-7777-4777-8777-777777777777'),
('10000000-0000-4000-8000-000000000015', 'Loft arty a Bordeaux', 'Loft colore et confortable dans un quartier vivant, parfait pour un couple ou un sejour creatif de quelques jours.', 155, 44.8378, -0.5792, '77777777-7777-4777-8777-777777777777'),
('10000000-0000-4000-8000-000000000016', 'Maison avec jardin a Nantes', 'Maison calme avec petit jardin et grande piece de vie, ideale pour une famille ou un sejour detendu.', 170, 47.2184, -1.5536, '88888888-8888-4888-8888-888888888888'),
('10000000-0000-4000-8000-000000000017', 'T3 plage sud a Nice', 'Appartement spacieux proche de la promenade, avec chambres confortables et belle luminosite toute la journee.', 195, 43.7102, 7.2620, '88888888-8888-4888-8888-888888888888'),
('10000000-0000-4000-8000-000000000018', 'Appartement calme a Montpellier', 'T2 tres calme avec deco sobre, bien situe pour profiter du centre ville puis rejoindre la mer.', 120, 43.6108, 3.8767, '99999999-9999-4999-8999-999999999999'),
('10000000-0000-4000-8000-000000000019', 'Maison blanche a Bonifacio', 'Maison lumineuse au style mediterraneen avec terrasse et vue degagee, parfaite pour un sejour au soleil.', 230, 41.3874, 9.1593, 'cccccccc-cccc-4ccc-8ccc-cccccccccccc'),
('10000000-0000-4000-8000-000000000020', 'Studio de charme a Brest', 'Studio de charme bien equipe avec ambiance marine, pratique pour un sejour solo ou un week end a deux.', 90, 48.3904, -4.4861, 'dddddddd-dddd-4ddd-8ddd-dddddddddddd');

