INSERT OR IGNORE INTO reviews (id, text, rating, user_id, place_id) VALUES
('20000000-0000-4000-8000-000000000001', 'Appartement propre et bien place, parfait pour un week end surf.', 5, '22222222-2222-4222-8222-222222222222', '10000000-0000-4000-8000-000000000001'),
('20000000-0000-4000-8000-000000000002', 'Sejour tres agreable, literie confortable et acces plage rapide.', 4, '77777777-7777-4777-8777-777777777777', '10000000-0000-4000-8000-000000000001'),
('20000000-0000-4000-8000-000000000003', 'Petit logement pratique et lumineux, ideal pour deux nuits.', 4, 'aaaaaaaa-aaaa-4aaa-8aaa-aaaaaaaaaaaa', '10000000-0000-4000-8000-000000000001'),
('20000000-0000-4000-8000-000000000004', 'Calme, propre et bien equipe, parfait pour teletravailler.', 5, 'bbbbbbbb-bbbb-4bbb-8bbb-bbbbbbbbbbbb', '10000000-0000-4000-8000-000000000002'),
('20000000-0000-4000-8000-000000000005', 'Tres bon emplacement et deco reussie, je reviendrai.', 5, '11111111-1111-4111-8111-111111111111', '10000000-0000-4000-8000-000000000004'),
('20000000-0000-4000-8000-000000000006', 'Loft spacieux, quartier vivant et tres bon accueil.', 4, '55555555-5555-4555-8555-555555555555', '10000000-0000-4000-8000-000000000004'),
('20000000-0000-4000-8000-000000000007', 'Belle terrasse et ambiance vacances tres reussie.', 5, '99999999-9999-4999-8999-999999999999', '10000000-0000-4000-8000-000000000005'),
('20000000-0000-4000-8000-000000000008', 'Maison pleine de charme avec un vrai esprit bord de mer.', 4, '44444444-4444-4444-8444-444444444444', '10000000-0000-4000-8000-000000000006'),
('20000000-0000-4000-8000-000000000009', 'Adresse authentique et tres bien tenue, sejour reposant.', 5, 'eeeeeeee-eeee-4eee-8eee-eeeeeeeeeeee', '10000000-0000-4000-8000-000000000006'),
('20000000-0000-4000-8000-000000000010', 'Chalet tres confortable avec vue superbe sur les montagnes.', 5, '22222222-2222-4222-8222-222222222222', '10000000-0000-4000-8000-000000000008'),
('20000000-0000-4000-8000-000000000011', 'Ideal pour une semaine ski, tres chaleureux le soir.', 4, '33333333-3333-4333-8333-333333333333', '10000000-0000-4000-8000-000000000008'),
('20000000-0000-4000-8000-000000000012', 'Nous avons adore le calme et la qualite des equipements.', 5, 'cccccccc-cccc-4ccc-8ccc-cccccccccccc', '10000000-0000-4000-8000-000000000008'),
('20000000-0000-4000-8000-000000000013', 'Appartement tres pratique pour profiter du centre et du lac.', 4, '55555555-5555-4555-8555-555555555555', '10000000-0000-4000-8000-000000000009'),
('20000000-0000-4000-8000-000000000014', 'Grande maison ideale avec enfants, jardin tres agreable.', 5, '11111111-1111-4111-8111-111111111111', '10000000-0000-4000-8000-000000000010'),
('20000000-0000-4000-8000-000000000015', 'Confortable, bien amenagee et parfaite pour de longues vacances.', 4, '66666666-6666-4666-8666-666666666666', '10000000-0000-4000-8000-000000000010'),
('20000000-0000-4000-8000-000000000016', 'Maison fraiche en ete et tres calme le soir.', 5, '88888888-8888-4888-8888-888888888888', '10000000-0000-4000-8000-000000000012'),
('20000000-0000-4000-8000-000000000017', 'Tres bon pied a terre pour Lyon, propre et bien pense.', 4, '77777777-7777-4777-8777-777777777777', '10000000-0000-4000-8000-000000000013'),
('20000000-0000-4000-8000-000000000018', 'Appartement pratique et lumineux, rien a redire.', 4, 'aaaaaaaa-aaaa-4aaa-8aaa-aaaaaaaaaaaa', '10000000-0000-4000-8000-000000000013'),
('20000000-0000-4000-8000-000000000019', 'Tres bon emplacement pour les balades en bord de mer.', 4, 'bbbbbbbb-bbbb-4bbb-8bbb-bbbbbbbbbbbb', '10000000-0000-4000-8000-000000000014'),
('20000000-0000-4000-8000-000000000020', 'Loft agreable et vivant, parfait pour decouvrir Bordeaux.', 5, '33333333-3333-4333-8333-333333333333', '10000000-0000-4000-8000-000000000015'),
('20000000-0000-4000-8000-000000000021', 'Adresse originale, propre et tres bien situee.', 4, '99999999-9999-4999-8999-999999999999', '10000000-0000-4000-8000-000000000015'),
('20000000-0000-4000-8000-000000000022', 'Appartement spacieux proche de la plage, super pour un groupe.', 5, '11111111-1111-4111-8111-111111111111', '10000000-0000-4000-8000-000000000017'),
('20000000-0000-4000-8000-000000000023', 'Tres bon sejour, chambres confortables et quartier agreable.', 4, '44444444-4444-4444-8444-444444444444', '10000000-0000-4000-8000-000000000017'),
('20000000-0000-4000-8000-000000000024', 'Bon rapport qualite prix et localisation ideale.', 4, 'eeeeeeee-eeee-4eee-8eee-eeeeeeeeeeee', '10000000-0000-4000-8000-000000000017'),
('20000000-0000-4000-8000-000000000025', 'T2 tres calme, parfait pour couper quelques jours.', 4, '22222222-2222-4222-8222-222222222222', '10000000-0000-4000-8000-000000000018'),
('20000000-0000-4000-8000-000000000026', 'Maison lumineuse avec une vraie atmosphere vacances.', 5, '55555555-5555-4555-8555-555555555555', '10000000-0000-4000-8000-000000000019'),
('20000000-0000-4000-8000-000000000027', 'Tres belle terrasse et logement impeccable.', 5, 'aaaaaaaa-aaaa-4aaa-8aaa-aaaaaaaaaaaa', '10000000-0000-4000-8000-000000000019'),
('20000000-0000-4000-8000-000000000028', 'Studio bien equipe et tres facile a vivre.', 4, 'cccccccc-cccc-4ccc-8ccc-cccccccccccc', '10000000-0000-4000-8000-000000000020');

